// ─── IKI KATMANLI LIMIT ─────────────────────────────────────────────────
// 1) IP basina GUNLUK limit: tek kullanicinin sistemi spam'lemesini engeller.
// 2) GLOBAL AYLIK limit: Apify TikTok Trending calistirmasi basina ~$0.10
//    (20 sonuc, TR proxy filtresi dahil) -- TUM kullanicilar arasinda
//    paylasilan gercek butceyi korur. IP limiti bunu KORUMAZ -- 50 farkli
//    kullanici gunde 1'er istek atsa bile toplam kota hizla biter. Apify'in
//    aylik $5 ucretsiz kredisi ~50 calistirmaya denk geldigi icin, pay
//    birakmak icin 50 degil 45'te kesiyoruz.
const PER_IP_DAILY_LIMIT = 50;
// NOT: 'Build Search Query' 2 yerine 4 hashtag kullanmaya basladi (fyp,
// kesfet, turkiye, trendturkiye) -- Apify muhtemelen her hashtag icin ayri
// ucretlendiriyor, yani calistirma basina maliyet ~2 katina cikabilir. Ilk
// gercek test sonrasi Apify Storage/Usage sayfasindan gercek maliyeti
// kontrol edip bu sayiyi ona gore ayarla -- simdilik ihtiyatli baslangic.
const GLOBAL_MONTHLY_SEARCH_LIMIT = 25;

const ip = $input.first().json.headers?.['x-forwarded-for']?.split(',')[0]?.trim() || $input.first().json.headers?.['x-real-ip'] || 'unknown';
const today = new Date().toISOString().slice(0, 10);
const monthKey = today.slice(0, 7); // 'YYYY-MM'
const ipKey = 'rl_trend_' + ip + '_' + today;
const globalKey = 'rl_trend_global_' + monthKey;

const staticData = $getWorkflowStaticData('global');
if (!staticData.rateLimits) staticData.rateLimits = {};

const ipCount = staticData.rateLimits[ipKey] || 0;
const globalCount = staticData.rateLimits[globalKey] || 0;

if (ipCount >= PER_IP_DAILY_LIMIT) {
  return [{ json: { rateLimitExceeded: true, reason: 'ip_daily' } }];
}
if (globalCount >= GLOBAL_MONTHLY_SEARCH_LIMIT) {
  return [{ json: { rateLimitExceeded: true, reason: 'global_monthly' } }];
}

staticData.rateLimits[ipKey] = ipCount + 1;
staticData.rateLimits[globalKey] = globalCount + 1;

const body = $input.first().json.body || $input.first().json;
return [{ json: { rateLimitExceeded: false, ...body } }];

const data = $input.first().json;
const systemMessage = `Sen bir içerik stratejisti ve format mining uzmanısın.

Görevin: Sosyal medyadan gelen gerçek trend videoların arkasındaki tekrarlanabilir FORMAT yapılarını çıkarmak ve kullanıcının sektörüne uyarlamak.

Temel kavramlar:
- FORMAT: Videonun kendisi değil, kurgu mantığı — hook + yapı + CTA kalıbı
- FORMAT MİNİNG: Başarılı videolardan soyut, tekrar kullanılabilir içerik şablonu çıkarmak
- FORMAT REPLİKASYON: Aynı kurgu yapısını farklı sektör/marka için uyarlamak

Önemli: Yüksek izlenme = iyi format değildir. Asıl hedef: çok izlenmiş + tekrar edilebilir + markaya uyarlanabilir + şu anda yükselen format.

Çıktı her zaman geçerli JSON olmalıdır. Markdown code block kullanma. Açıklama metni ekleme. Sadece JSON döndür.

Önemli: Düşünme sürecini kısa tut. Hemen JSON çıktısına geç.`;
const apiBody = {
  model: 'MiniMax-M3',
  max_completion_tokens: 20000,
  messages: [
    { role: 'system', content: systemMessage },
    { role: 'user', content: data.prompt || '' }
  ]
};
return [{ json: { ...data, apiBody } }];

// FORMAT MİNİNG — Response Transform
// Yeni çıktı yapısı: trend_formatlar[] (sektore_ozgu_uyarlamalar[] içeriyor)
// Eski videos[] yapısıyla geriye dönük uyumluluk korunuyor (HTML bunu okuyabilsin)

const ctx = $('Build Request Body').first().json;
const apiData = $input.first().json;

// MiniMax-M3 reasoning modeli cevabı farklı alanlarda döndürebilir
const msg = apiData.choices?.[0]?.message || {};
const finishReason = apiData.choices?.[0]?.finish_reason || '';
// content boşsa reasoning_content'e bak (bazı MiniMax sürümleri)
let text = msg.content || msg.reasoning_content || '';
// Tüm apiData'yı debug için sakla
const _debugApiKeys = Object.keys(apiData);
const _debugMsgKeys = Object.keys(msg);

// <think> bloğunu temizle
const thinkEnd = text.lastIndexOf('</think>');
if (thinkEnd !== -1) text = text.slice(thinkEnd + '</think>'.length);

// JSON bloğunu çıkar
const jsonStart = text.indexOf('{');
const jsonEnd = text.lastIndexOf('}');
if (jsonStart !== -1 && jsonEnd !== -1) text = text.slice(jsonStart, jsonEnd + 1);

// Türkçe encoding düzeltmesi (MiniMax GBK sorunu)
const TR_RESTORE = {
  '\u7109': 'ü', '\u8267': 'ş', '\u679a': 'ö', '\u83bd': 'ç',
  '\u8c0b': 'ı', '\u81d2': 'ğ', '\u811f': 'Ç', '\u813a': 'Ü',
  '\u8266': 'Ş', '\u8130': 'Ö', '\u81d1': 'Ğ', '\u964c': 'İ',
};
const TR_KEYS = Object.keys(TR_RESTORE).join('');
const TR_RE = new RegExp('[' + TR_KEYS + ']', 'g');
text = text.replace(TR_RE, ch => TR_RESTORE[ch] || ch);

function tryParseJson(raw) {
  try { return { ok: true, value: JSON.parse(raw) }; }
  catch (e1) {
    // Adım 1: Trailing comma temizle
    let repaired = raw
      .replace(/,\s*([\]}])/g, '$1')
      .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, '');
    try { return { ok: true, value: JSON.parse(repaired) }; }
    catch (e2) {
      // Adım 2: Kesik JSON tamir — son geçerli } veya ] bulup kes
      // Trend_formatlar varsa kurtarmaya çalış
      const fmIdx = repaired.indexOf('"trend_formatlar"');
      if (fmIdx !== -1) {
        // En son tamamlanmış ] bul (sektore_ozgu_uyarlamalar kapanmış olsun)
        let bestEnd = -1;
        let depth = 0;
        for (let i = 0; i < repaired.length; i++) {
          if (repaired[i] === '{' || repaired[i] === '[') depth++;
          else if (repaired[i] === '}' || repaired[i] === ']') { depth--; if (depth <= 1) bestEnd = i; }
        }
        if (bestEnd > fmIdx) {
          // Kes ve kapat
          let truncated = repaired.slice(0, bestEnd + 1);
          // trend_formatlar dizisini kapat
          if (!truncated.trimEnd().endsWith(']}')) {
            truncated = truncated.replace(/,?\s*$/, '') + ']}';
          }
          truncated += '}';
          try { return { ok: true, value: JSON.parse(truncated) }; } catch(e3) {}
        }
      }
      return { ok: false, error: e1.message || String(e1) };
    }
  }
}

function extractErrorPosition(msg) {
  const m = /position (\d+)/.exec(msg || '');
  return m ? parseInt(m[1], 10) : null;
}

function buildDebugSnippet(raw, errMsg) {
  const pos = extractErrorPosition(errMsg);
  if (pos !== null) {
    const start = Math.max(0, pos - 350);
    const marker = Math.min(pos, raw.length) - start;
    return raw.slice(start, start + marker) + ' >>>HATA_BURADA<<< ' + raw.slice(start + marker, Math.min(raw.length, pos + 150));
  }
  return raw.slice(0, 800);
}

const parsed = tryParseJson(text);
let result;
let parseError = null;
let debugSnippet = null;
if (parsed.ok) {
  result = parsed.value;
} else {
  result = { trend_formatlar: [], sektör_özeti: '' };
  parseError = parsed.error;
  debugSnippet = buildDebugSnippet(text, parsed.error);
}

const formatlar = result.trend_formatlar || [];
const sektorOzeti = result['sektör_özeti'] || result.sektor_ozeti || '';

const dateStr = new Date().toLocaleDateString('tr-TR', { day: 'numeric', month: 'long', year: 'numeric' });
const sectorText = (ctx.sector === 'ALL' || !ctx.sector) ? 'Tüm Sektörler' : ctx.sector;
const bizText = ctx.biz || 'İşletmeniz';
const VALID_MODES = ['instant', 'once', 'schedule'];
const safeMode = VALID_MODES.includes(ctx.mode) ? ctx.mode : 'instant';

// Skor rozetleri
function skorRozeti(skor) {
  if (skor >= 85) return '🔥';
  if (skor >= 70) return '⬆️';
  return '➡️';
}
function uretimRengi(seviye) {
  if (seviye === 'Çok Düşük' || seviye === 'Düşük') return '#DCFCE7';
  if (seviye === 'Orta') return '#FEF9C3';
  return '#FEE2E2';
}

// Email içeriği (düz metin)
let emailContent = `Merhaba! ${bizText} için ${dateStr} tarihli trend video format raporu:\n\n`;
formatlar.forEach((f, i) => {
  emailContent += `FORMAT #${f.sira || i+1} — ${f.format_adi || ''}\n`;
  emailContent += `Tip: ${f.format_tipi || ''} | Trend: ${f.trend_skoru || 'N/A'}/100 | Uyarlanabilirlik: ${f.uyarlanabilirlik_skoru || 'N/A'}/100\n`;
  emailContent += `Kurgu: ${f.kurgu_yapisi || ''}\n`;
  emailContent += `Hook: ${f.ornek_hook || ''}\n`;
  const birincil = (f.sektore_ozgu_uyarlamalar || [])[0];
  if (birincil) {
    emailContent += `\n${birincil.sektor} için:\n  Hook: ${birincil.hook || ''}\n  Senaryo: ${birincil.senaryo_taslagi || ''}\n`;
  }
  emailContent += `\n---\n\n`;
});
if (sektorOzeti) emailContent += `Sektör Özeti: ${sektorOzeti}\n`;

// HTML email gövdesi
const realSourcesHtml = (ctx.searchResultsRaw && ctx.searchResultsRaw.length)
  ? `<div style="margin-top:1.5rem;padding-top:1rem;border-top:1px dashed #E2E0D8">
     <div style="font-size:12px;color:#6B6963;font-weight:500;margin-bottom:.5rem">📹 İlham alınan TikTok videoları:</div>` +
    [...ctx.searchResultsRaw].sort((a,b)=>(b.playCount||0)-(a.playCount||0)).slice(0,5).map(r =>
      `<div style="font-size:12px;margin-bottom:.35rem">
         <a href="${r.webVideoUrl}" style="color:#1D9E75;text-decoration:none" target="_blank">
           @${(r.authorMeta&&r.authorMeta.name)||'bilinmiyor'} — ${(r.playCount||0).toLocaleString('tr-TR')} izlenme
         </a>
       </div>`).join('') + `</div>` : '';

const formatCards = formatlar.map(f => {
  const uyarlamalar = (f.sektore_ozgu_uyarlamalar || []).map(u =>
    `<div style="background:#F7F6F2;border-radius:8px;padding:10px 12px;margin-bottom:8px">
       <div style="font-size:11px;font-weight:600;color:#1D9E75;margin-bottom:4px">📍 ${u.sektor}</div>
       <div style="font-size:12px;color:#1C1B19;margin-bottom:4px"><strong>Hook:</strong> ${u.hook || ''}</div>
       <div style="font-size:12px;color:#6B6963">${u.senaryo_taslagi || ''}</div>
     </div>`).join('');
  return `<div style="border:0.5px solid #E2E0D8;border-radius:12px;padding:1.25rem;margin-bottom:1rem">
    <div style="display:flex;align-items:center;gap:8px;margin-bottom:.75rem">
      <div style="font-size:20px">${skorRozeti(f.trend_skoru || 0)}</div>
      <div>
        <div style="font-size:15px;font-weight:600;color:#1C1B19">${f.format_adi || ''}</div>
        <div style="font-size:11px;color:#6B6963">${f.format_tipi || ''}</div>
      </div>
    </div>
    <div style="display:flex;gap:8px;margin-bottom:.75rem">
      <span style="font-size:11px;padding:3px 8px;background:#F0FAF6;border:0.5px solid #9FE1CB;border-radius:6px;color:#085041">Trend ${f.trend_skoru || '?'}/100</span>
      <span style="font-size:11px;padding:3px 8px;background:#EFF6FF;border:0.5px solid #93C5FD;border-radius:6px;color:#1E40AF">Uyarlanabilirlik ${f.uyarlanabilirlik_skoru || '?'}/100</span>
      <span style="font-size:11px;padding:3px 8px;background:${uretimRengi(f.uretim_zorlugu)};border-radius:6px;color:#374151">Üretim: ${f.uretim_zorlugu || '?'}</span>
    </div>
    <div style="font-size:12px;color:#6B6963;margin-bottom:.5rem"><strong>Kurgu:</strong> ${f.kurgu_yapisi || ''}</div>
    <div style="background:#DCF8C6;border-radius:8px;padding:8px 10px;font-size:12px;color:#1C1B19;margin-bottom:.75rem"><strong>Hook:</strong> ${f.ornek_hook || ''}</div>
    <div style="font-size:11px;font-weight:600;color:#374151;margin-bottom:.5rem">🎯 Sektöre Özel Uyarlamalar:</div>
    ${uyarlamalar}
  </div>`;
}).join('');

const htmlBody = `<!DOCTYPE html><html lang="tr"><head><meta charset="UTF-8"></head>
<body style="font-family:system-ui,sans-serif;background:#F7F6F2;padding:2rem">
<div style="max-width:680px;margin:0 auto;background:#fff;border-radius:16px;padding:2rem;border:0.5px solid #E2E0D8">
  <div style="color:#1D9E75;font-size:13px;font-weight:500;letter-spacing:.04em;margin-bottom:1.5rem">KOLAY KOBİ — TREND FORMAT RAPORU</div>
  <h1 style="font-size:22px;color:#1C1B19;margin-bottom:.4rem">Trend Video Format Mining</h1>
  <p style="font-size:14px;color:#6B6963;margin-bottom:2rem">
    <strong>${bizText}</strong> — ${sectorText}<br/>Tarih: ${dateStr}
  </p>
  ${sektorOzeti ? `<div style="background:#F0FAF6;border-radius:8px;padding:12px 14px;margin-bottom:1.5rem;font-size:13px;color:#085041">📊 ${sektorOzeti}</div>` : ''}
  ${formatCards}
  ${realSourcesHtml}
  <div style="background:#F0FAF6;border-radius:8px;padding:1rem;margin-top:1.5rem;text-align:center">
    <p style="font-size:13px;color:#0F6E56;margin:0">Bu rapor Kolay KOBİ Trend Video Bulucu ile oluşturuldu.</p>
    <a href="https://kolaykobi.com" style="display:inline-block;background:#1D9E75;color:#fff;padding:10px 24px;border-radius:8px;text-decoration:none;font-size:14px;margin-top:.75rem">Kolay KOBİ'yi Aç</a>
  </div>
</div></body></html>`;

// Geriye dönük uyumluluk — HTML bu yapıyı okuyabilsin
const videos = formatlar.map(f => ({
  rank: f.sira,
  title: f.format_adi,
  format_tipi: f.format_tipi,
  format_aciklamasi: f.format_aciklamasi,
  kurgu_yapisi: f.kurgu_yapisi,
  sure: f.sure,
  ornek_hook: f.ornek_hook,
  trendScore: f.trend_skoru,
  uyarlanabilirlik_skoru: f.uyarlanabilirlik_skoru,
  uretim_zorlugu: f.uretim_zorlugu,
  marka_guvenligi: f.marka_guvenligi,
  sektore_ozgu_uyarlamalar: f.sektore_ozgu_uyarlamalar || [],
  // Birincil sektör uyarlaması — hızlı erişim için
  adaptation: (f.sektore_ozgu_uyarlamalar || [])[0]?.senaryo_taslagi || '',
  inspiredBy: f.esinlenilen_video_link || null,
}));

return [{ json: {
  content: [{ type: 'text', text }],
  trend_formatlar: formatlar,
  sektör_özeti: sektorOzeti,
  videos, // geriye dönük uyumluluk
  realSources: ctx.searchResultsRaw || [],
  email: ctx.email || '',
  biz: bizText,
  sector: ctx.sector || '',
  tones: ctx.tones || [],
  mode: safeMode,
  hour: ctx.hour || '',
  days: ctx.days || [],
  audience: ctx.audience || '',
  note: ctx.note || '',
  prompt: ctx.prompt || '',
  emailContent,
  htmlBody,
  ctaText: '',
  parseError,
  rawModelTextSnippet: parseError ? debugSnippet : undefined,
  rawModelTextFull: parseError ? text : undefined,
} }];

const data = $input.first().json;
const staticData = $getWorkflowStaticData('global');
if (!staticData.schedules) staticData.schedules = {};
const id = 'sch_' + Date.now() + '_' + Math.random().toString(36).slice(2, 8);
staticData.schedules[id] = {
  id,
  biz: data.biz || 'İşletme',
  sector: data.sector || 'ALL',
  email: data.email || '',
  tones: data.tones || [],
  audience: data.audience || '',
  note: data.note || '',
  prompt: data.prompt || '',
  hour: data.hour,
  days: data.days || [],
  createdAt: new Date().toISOString(),
  active: true,
};
return [{ json: { ...data, scheduleId: id, scheduleSaved: true } }];

// Webhook zaten 'Respond With Job ID' ile cevap verdi; burada tekrar
// HTTP yaniti DONMUYORUZ, sadece sonucu static data'ya job_id altinda yaziyoruz.
//
// YENI: "Response Transform" JSON.parse basarisiz olduysa (parseError dolu),
// bunu ARTIK sessiz bir "completed, videos:[]" olarak degil, acik bir
// status:'error' olarak isaretliyoruz — boylece kullanici gercek nedeni gorur.
const staticData = $getWorkflowStaticData('global');
const jobId = $('Create Job').first().json.jobId;
const rt = $('Response Transform').first().json;
const payload = { ...rt, ...$json };

if (staticData.jobs && staticData.jobs[jobId]) {
  if (rt.parseError) {
    staticData.jobs[jobId] = {
      status: 'error',
      createdAt: staticData.jobs[jobId].createdAt,
      error: 'AI çıktısı geçerli JSON değildi: ' + rt.parseError + (rt.rawModelTextSnippet ? ' | Ham metin (ilk 800 karakter): ' + rt.rawModelTextSnippet : ''),
    };
  } else {
    staticData.jobs[jobId] = { status: 'completed', createdAt: staticData.jobs[jobId].createdAt, ...payload };
  }
}
return [{ json: payload }];

const data = $input.first().json;
const staticData = $getWorkflowStaticData('global');
if (!staticData.jobs) staticData.jobs = {};
// 30 dakikadan eski job kayitlarini temizle (static data sismesin)
const now = Date.now();
Object.keys(staticData.jobs).forEach(id => {
  if (now - (staticData.jobs[id].createdAt || 0) > 30 * 60 * 1000) delete staticData.jobs[id];
});
const jobId = now.toString(36) + Math.random().toString(36).slice(2, 10);
staticData.jobs[jobId] = { status: 'pending', createdAt: now };
return [{ json: { ...data, jobId } }];

// DUZELTME: onceki versiyon "err.error" bir OBJE oldugunda onu dogrudan
// error alanina yaziyordu; bu da istemci tarafinda "[object Object]" olarak
// gorunuyordu. Artik hatanin gercek metnini cok katmanli/guvenli sekilde
// cikariyoruz, boylece gercek MiniMax/n8n hatasini goruruz.
const staticData = $getWorkflowStaticData('global');
const jobId = $('Create Job').first().json.jobId;
const err = $input.first().json;

function extractMessage(e) {
  if (!e) return 'Bilinmeyen hata';
  if (typeof e === 'string') return e;
  if (typeof e.message === 'string' && e.message) return e.message;
  if (typeof e.error === 'string' && e.error) return e.error;
  if (e.error && typeof e.error === 'object') {
    if (typeof e.error.message === 'string' && e.error.message) return e.error.message;
    if (typeof e.error.error === 'string' && e.error.error) return e.error.error;
    try { return JSON.stringify(e.error).slice(0, 400); } catch (_) {}
  }
  if (typeof e.description === 'string' && e.description) return e.description;
  if (typeof e.statusCode !== 'undefined') return `HTTP ${e.statusCode}: ${JSON.stringify(e).slice(0, 300)}`;
  try { return JSON.stringify(e).slice(0, 400); } catch (_) { return 'Bilinmeyen hata (JSON.stringify basarisiz)'; }
}

const errorMessage = extractMessage(err);

if (staticData.jobs && staticData.jobs[jobId]) {
  staticData.jobs[jobId] = { status: 'error', createdAt: staticData.jobs[jobId].createdAt, error: errorMessage };
}
return [{ json: { ok: false, error: errorMessage } }];

const q = $input.first().json.query || {};
const jobId = q.jobId;
const staticData = $getWorkflowStaticData('global');
const job = (staticData.jobs || {})[jobId];
if (!job) return [{ json: { status: 'not_found' } }];
return [{ json: job }];

const data = $input.first().json;
// Kullanicinin istedigi: sektore ozel arama DEGIL, genel olarak GERCEKTEN
// trend olan (yuksek izlenmeli) videolar. Bunlar sonradan MiniMax tarafindan
// sektore uyarlanacak (penguen -> lojistik mantigi). Bu yuzden sabit,
// genis kapsamli trend hashtag'leri kullaniyoruz, sektore gore degil.
// 'turkiye' ve 'trendturkiye' eklendi: 'fyp' ve 'kesfet' global etiketler
// oldugu icin sonuclarin cogu Turkce olmayan icerik getiriyordu -- bu
// ikisi Turkiye'deki kullanicilarin gordugu/kullandigi trendlere agirlik
// verip Turkce/yerel sonuc oranini artiriyor.
const hashtags = ['fyp', 'keşfet', 'turkiye', 'trendturkiye'];
return [{ json: { ...data, hashtags } }];

// FORMAT MİNİNG — Apify TikTok verilerinden format yapısı çıkarma
// Build Search Query'den context'i geri al (HTTP node taşımaz)
const ctx = $('Build Search Query').first().json;
const items = $input.all().map(i => i.json);
const isError = items.length === 1 && items[0] && items[0].error;
const videos = (!isError && items.length) ? items : [];

const sector = ctx.sector || 'Genel';
const purpose = ctx.purpose || 'Marka bilinirliği';

let searchBlock;
if (videos.length) {
  const top = videos.slice(0, 10).sort((a, b) => (b.playCount || 0) - (a.playCount || 0));
  searchBlock = `

═══ GERÇEK TREND TİKTOK VİDEOLARI (bugün çekildi) ═══
` +
    top.map((v, i) => [
      `${i + 1}. @${v.authorMeta?.name || 'bilinmiyor'} — ${(v.playCount || 0).toLocaleString('tr-TR')} izlenme, ${(v.diggCount || 0).toLocaleString('tr-TR')} beğeni`,
      `   Açıklama: ${(v.text || '').slice(0, 200)}`,
      `   Link: ${v.webVideoUrl || 'yok'}`
    ].join('
')).join('
') +
    `

═══ GÖREVİN ═══
` +
    `Yukarıdaki videolardan tekrar kullanılabilir FORMAT yapılarını çıkar.
` +
    `Videonun kendisini değil, KURGU MANTIĞINI analiz et:
` +
    `  - Hook: İlk 1-3 saniyede ne söyleniyor/gösteriliyor?
` +
    `  - Yapı: Sahne sırası nasıl? (örn: problem → çözüm → CTA)
` +
    `  - Format tipi: POV / Expectation vs Reality / Nobody Knows I / Mini skeç / Text overlay / vb.
` +
    `
ÖNEMLİ FİLTRE: Tekil/kişiye özel içerikleri (bir kişinin o anki hikayesi, kişisel itiraf vb.) ATLA.
` +
    `SADECE soyutlanabilir, tekrar kullanılabilir format içeren videoları seç.
` +
    `
