// Çünkü HTML prompt'u hem 'eski 7 video' hem 'format mining' talimatını içerince model karışıyor
const basePrompt = `${sector} sektörü için sosyal medya trend video formatlarını analiz et ve format mining yap. Ton: ${ctx.tones ? (Array.isArray(ctx.tones) ? ctx.tones.join(' + ') : ctx.tones) : 'Eğlendirici'}. Hedef kitle: ${ctx.audience || 'KOBİ sahipleri'}.${ctx.biz ? ' İşletme: ' + ctx.biz + '.' : ''}${ctx.note ? ' Ek talimat: ' + ctx.note : ''}`;
const augmentedPrompt = basePrompt + searchBlock + schemaBlock;
return [{ json: { ...ctx, prompt: augmentedPrompt, searchResultsRaw: videos.length ? videos : null } }];
